const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const syncSelects=enhanceSelects([$('#periodInput'),$('#accountInput')]);
const paths={search:'m21 21-4.5-4.5M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0',scan:'M8 3H4a1 1 0 0 0-1 1v4m13-5h4a1 1 0 0 1 1 1v4M3 16v4a1 1 0 0 0 1 1h4m8 0h4a1 1 0 0 0 1-1v-4M7 12h10m-5-5v10',history:'M3 11a9 9 0 1 1 2.4 7M3 4v7h7m2-4v5l3 2',bookmark:'M6 3h12v18l-6-4-6 4V3Z',image:'M3 3h18v18H3V3Zm0 13 6-6 5 5 3-3 4 4M16 7h.01',settings:'m9 3-1 3-3 1-2 3 2 3v3l3 1 2 3h4l2-3 3-1v-3l2-3-2-3-3-1-1-3H9Zm6 9a3 3 0 1 1-6 0 3 3 0 0 1 6 0',moon:'M21 12.8A9 9 0 0 1 11.2 3 9 9 0 1 0 21 12.8Z',sparkles:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Zm7-1v4m-2-2h4',arrow:'M4 12h16m-6-6 6 6-6 6',layers:'m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5',chart:'M4 3v18h17M8 16v-5m5 5V6m5 10v-8',target:'M21 12a9 9 0 1 1-9-9m5-1-5 10m0 0 8-4M16 12a4 4 0 1 1-4-4',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Zm-4 9 3 3 5-6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 15V3m-5 5 5-5 5 5M4 16v5h16v-5',refresh:'M20 7A9 9 0 0 0 4 8m0 9a9 9 0 0 0 16-1M20 2v6h-6M4 22v-6h6',calculator:'M5 2h14v20H5V2Zm3 4h8M8 11h1m6 0h1m-8 4h1m6 0h1m-8 4h1m6 0h1',plug:'M8 2v5m8-5v5M5 7h14v3a7 7 0 0 1-14 0V7Zm7 10v5',x:'m6 6 12 12M18 6 6 18',check:'m5 12 4 4L19 6',file:'M14 2H4v20h16V8l-6-6Zm0 0v6h6M8 13h8m-8 4h6',database:'M20 5c0 2-16 2-16 0s16-2 16 0Zm0 0v14c0 2-16 2-16 0V5m0 7c0 2 16 2 16 0',copy:'M8 8h13v13H8V8ZM4 16H2V2h14v2',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7'};
function icon(name){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(paths[name]||paths.file)+'"/></svg>'}
function icons(root=document){syncSelects();root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon)})}
const empty=(title,detail,name='search')=>'<div class="empty-state"><span data-icon="'+name+'"></span><h3>'+esc(title)+'</h3><p>'+esc(detail)+'</p></div>';
const link=(value,label)=>{const u=url(value);return u?'<a href="'+esc(u)+'" target="_blank" rel="noopener noreferrer">'+esc(label||new URL(u).hostname)+' ↗</a>':'Chưa có dữ liệu'};
const id=()=>globalThis.crypto?.randomUUID?.()||'id-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let reports=[],watchlist=read('giasat-watchlist',[]),report=null,view='research',tab='overview',depth='high',busy=false,job=null,connected=false,ready=false,token='',toastTimer;
try{reports=read('giasat-v2-reports',read('giasat-reports',[])).map(normalizeReport)}catch{reports=[]}
let backend=read('giasat-backend','')||(location.port==='4318'?location.origin:'http://localhost:4318');
try{token=sessionStorage.getItem('giasat-session:'+backend)||''}catch{}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
function persist(){try{localStorage.setItem('giasat-v2-reports',JSON.stringify(reports));localStorage.setItem('giasat-watchlist',JSON.stringify(watchlist))}catch{toast('Bộ nhớ trình duyệt đầy hoặc bị chặn. Hãy xuất JSON để giữ dữ liệu.')}counts()}
function counts(){$('#historyCount').textContent=reports.length;$('#watchCount').textContent=watchlist.length}
function saveReport(){if(!report)return;reports=[report,...reports.filter(r=>r.id!==report.id)].slice(0,80);persist()}
function showView(next){view=next;['research','history','watchlist','assets'].forEach(v=>$('#'+v+'View').hidden=v!==next);$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===next));$('#pageTitle').textContent={research:'Nghiên cứu thị trường',history:'Lịch sử báo cáo',watchlist:'Sản phẩm theo dõi',assets:'Tư liệu & hình ảnh'}[next];if(next==='history')renderHistory();if(next==='watchlist')renderWatchlist();if(next==='assets'&&report&&!$('#imageProduct').value)$('#imageProduct').value=report.product;icons();window.scrollTo({top:0,behavior:'smooth'})}
$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();showView('research')};
function setTab(next){tab=next;['overview','competitors','insights','sources'].forEach(t=>$('#'+t+'Tab').hidden=t!==next);$$('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===next);b.setAttribute('aria-selected',b.dataset.tab===next)});icons()}
$$('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));
$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('#methodBtn').onclick=()=>$('#methodDialog').showModal();
document.documentElement.dataset.theme=read('giasat-theme','light');$('#themeBtn').onclick=()=>{const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;try{localStorage.setItem('giasat-theme',JSON.stringify(t))}catch{}};
document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='n'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('dialog[open]')){e.preventDefault();showView('research');$('#productInput').focus()}});
function confirmAction(title,message,reason=false){return new Promise(resolve=>{$('#confirmTitle').textContent=title;$('#confirmText').textContent=message;$('#reasonField').hidden=!reason;$('#excludeReason').value='';const d=$('#confirmDialog');const finish=value=>{d.close();resolve(value)};$('#confirmNo').onclick=()=>finish(null);$('#confirmYes').onclick=()=>{const value=$('#excludeReason').value.trim();if(reason&&!value){$('#excludeReason').focus();return}finish(reason?value:true)};d.oncancel=()=>resolve(null);d.showModal()})}
async function api(path,{method='GET',body,timeout=15000}={}){try{const r=await fetch(backend+path,{method,headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(timeout)});const data=await r.json();if(!r.ok)throw new Error(data.error||'Máy chủ chưa xử lý được yêu cầu.');return data}catch(e){if(e.name==='TypeError'||e.name==='TimeoutError')throw new Error('Không kết nối được máy chủ. Kiểm tra máy chủ trên PC, địa chỉ và quyền truy cập mạng nội bộ của trình duyệt.');throw e}}
function statusUI(){document.body.classList.toggle('connected',connected&&ready);$('#engineStatus').textContent=connected?(ready?'Đã sẵn sàng tìm kiếm':'Cần đăng nhập dịch vụ'):'Chưa kết nối · Nhấn để thiết lập';$('#topStatus').textContent=connected?(ready?'Đã kết nối':'Cần đăng nhập'):'Kết nối'}
async function checkConnection(auto=false){try{if(auto&&backend===location.origin&&!token){const s=await api('/api/connect',{method:'POST',body:{local:true}});token=s.token;try{sessionStorage.setItem('giasat-session:'+backend,token)}catch{}}const s=await api('/api/health',{timeout:3500});if(auto&&backend===location.origin&&s.ok&&!s.provider){token="";return checkConnection(true)}connected=s.ok&&!!s.provider;ready=!!s.ready;statusUI();return connected}catch{connected=false;ready=false;statusUI();return false}}
async function openConnect(){$('#backendInput').value=backend;$('#connectionMessage').textContent='';$('#pinInput').value='';$('#pairingDetails').innerHTML='';$('#connectionDialog').showModal();if(connected){try{const d=await api('/api/pairing');$('#pairingDetails').innerHTML='<div class="pairing-card">Ghép nối điện thoại cùng Wi‑Fi<div class="pairing-code">'+esc(d.pin)+'</div>'+d.urls.filter(u=>!u.includes('localhost')).map(u=>link(u,u)).join('')+'<p>Mở địa chỉ trên điện thoại và nhập mã. Không chia sẻ mã với người khác.</p></div>'}catch{}}}
$('#connectBtn').onclick=openConnect;$('#mobileConnect').onclick=openConnect;
$('#connectionForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;$('#connectionMessage').textContent='Đang kiểm tra…';try{const u=new URL($('#backendInput').value);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw new Error('Địa chỉ phải là HTTP/HTTPS, không chứa tài khoản.');backend=u.origin;token='';const result=await api('/api/connect',{method:'POST',body:{pin:$('#pinInput').value.trim(),local:backend===location.origin}});token=result.token;try{localStorage.setItem('giasat-backend',JSON.stringify(backend));sessionStorage.setItem('giasat-session:'+backend,token)}catch{}await checkConnection();$('#connectionMessage').textContent=ready?'Đã kết nối. Bạn có thể bắt đầu nghiên cứu.':'Máy chủ đã kết nối nhưng chưa có phiên dịch vụ. Xem hướng dẫn đăng nhập trong thư mục dự án.';if(ready){$('#connectionDialog').close();toast('Máy chủ đã sẵn sàng.')}}catch(err){$('#connectionMessage').textContent=err.message;statusUI()}finally{button.disabled=false}};
function showError(message){$('#errorPanel').hidden=false;$('#errorPanel').innerHTML='<b>Chưa hoàn tất nghiên cứu</b><div>'+esc(message)+'</div><button id="errorConnect">Kiểm tra kết nối →</button>'+(job?'<button id="resumeBtn">Tiếp tục nhận kết quả →</button>':'');$('#errorConnect').onclick=openConnect;if($('#resumeBtn'))$('#resumeBtn').onclick=()=>pollJob();}
function formData(){return {product:$('#productInput').value.trim(),period:$('#periodInput').value,account:$('#accountInput').value,depth}}
function setBusy(value){busy=value;$('#researchBtn').disabled=value;$('#rerunBtn').disabled=value;$('#progressPanel').hidden=!value;if(value){$('#errorPanel').hidden=true;$('#progressPanel').scrollIntoView({behavior:'smooth',block:'nearest'})}}
async function beginResearch(config=formData()){if(busy)return toast('Một nghiên cứu đang chạy.');if(!config.product)return $('#productInput').focus();showView('research');if(!connected||!ready){await checkConnection(true);if(!connected||!ready){await openConnect();toast('Kết nối máy chủ để tìm kiếm tự động.');return}}setBusy(true);$$('[data-step]').forEach(el=>{el.className='';el.querySelector('small').textContent='Đang chờ'});$('#progressTitle').textContent='Đang nghiên cứu '+config.product;$('#progressSub').textContent='Tìm kiếm ba góc độ và giữ lại nguồn tham chiếu.';try{const r=await api('/api/research',{method:'POST',body:config,timeout:30000});job=r.id;try{sessionStorage.setItem('giasat-job',job)}catch{}await pollJob()}catch(e){setBusy(false);showError(e.message)}}
async function pollJob(){if(!job)return;setBusy(true);let errors=0;const started=Date.now();try{while(job&&Date.now()-started<390000){let data;try{data=await api('/api/jobs/'+job);errors=0}catch(e){if(++errors>=3)throw e;await new Promise(r=>setTimeout(r,2000));continue}for(const ev of data.events||[]){const el=$('[data-step="'+ev.scope+'"]');if(el){el.className=ev.status;el.querySelector('small').textContent=ev.status==='done'?((ev.sources||0)+' nguồn tham chiếu'):ev.status==='error'?'Chưa lấy được dữ liệu':'Đang tìm web…'}if(ev.scope==='fx')$('#progressSub').textContent='Đang đối chiếu tỷ giá USD/VNĐ có nguồn.'}if(data.status==='done'){report=normalizeReport(data.result);saveReport();job=null;try{sessionStorage.removeItem('giasat-job')}catch{}renderReport();setTab('overview');toast('Đã tạo và lưu báo cáo. Hãy kiểm tra nguồn trước khi chốt giá.');$('#reportPanel').scrollIntoView({behavior:'smooth',block:'start'});break}if(['error','cancelled'].includes(data.status)){job=null;try{sessionStorage.removeItem('giasat-job')}catch{}throw new Error(data.error||'Nghiên cứu đã được hủy.')}await new Promise(r=>setTimeout(r,1700))}if(job)throw new Error('Nghiên cứu mất nhiều thời gian. Bạn có thể tiếp tục nhận kết quả.')}catch(e){showError(e.message)}finally{setBusy(false)}}
$('#searchForm').onsubmit=e=>{e.preventDefault();beginResearch()};$('#depthBtn').onclick=()=>{depth=depth==='high'?'medium':'high';$('#depthBtn').innerHTML=icon('layers')+(depth==='high'?' Nghiên cứu sâu':' Nghiên cứu nhanh');$('#depthBtn').setAttribute('aria-pressed',depth==='high')};
$$('[data-product]').forEach(b=>b.onclick=()=>{$('#productInput').value=b.dataset.product;$('#productInput').focus()});
$('#cancelBtn').onclick=async()=>{if(job){try{await api('/api/jobs/'+job,{method:'DELETE'});toast('Đã gửi yêu cầu hủy.')}catch(e){toast(e.message)}}};
function loadReport(r){report=r;$('#productInput').value=r.product;$('#periodInput').value=r.period;$('#accountInput').value=r.account;showView('research');renderReport();setTab('overview');$('#reportPanel').scrollIntoView({behavior:'smooth',block:'start'})}
function sourcesOf(r){const m=new Map();for(const s of [...r.sources,...r.entries.map(e=>({url:e.url,title:e.seller})),...r.news.map(e=>({url:e.url,title:e.title})),...r.marketing.map(e=>({url:e.url,title:e.text}))])if(url(s.url))m.set(s.url,s);return [...m.values()]}
function statCard(title,value,note,name,highlight=false,missing=false){return '<article class="stat '+(highlight?'highlight':'')+'"><div class="stat-top">'+esc(title)+icon(name)+'</div><b class="stat-value '+(missing?'missing':'')+'">'+esc(value)+'</b><small>'+esc(note)+'</small></article>'}
function renderReport(){if(!report)return;const s=stats(report),tr=trend(report,reports),conf=confidence(report),sources=sourcesOf(report);$('#welcomePanel').hidden=true;$('#reportPanel').hidden=false;$('#reportTitle').textContent=report.product;$('#reportMeta').textContent=(report.period==='year'?'1 năm':'1 tháng')+' · '+report.account+' · '+time(report.createdAt)+' · Đã lưu trên trình duyệt';$('#reportMode').textContent=report.mode==='live'?'WEB RESEARCH':'NGUỒN THỦ CÔNG';$('#competitorCount').textContent=report.entries.length;$('#sourceCount').textContent=sources.length;
 const official=[...new Set(s.official.map(e=>e.price))];$('#statsGrid').innerHTML=statCard('Giá chính hãng',official.length===1?money(official[0]):official.length?'Nhiều mức giá':'Chưa có dữ liệu',official.length>1?official.map(money).join(' / '):'Cùng thời hạn và hình thức','shield',false,!official.length)+statCard('Trung vị reseller',money(s.median),s.reseller.length+' bản ghi tương đương','chart',true,s.median===null)+statCard('Khoảng giá reseller',s.min===null?'Chưa có dữ liệu':money(s.min),s.max===null?'Chưa có giá để so sánh':'Cao nhất '+money(s.max),'layers',false,s.min===null)+statCard('Độ tin cậy',conf.label,conf.note,'target');
 let notes=report.warnings.map(w=>'<div class="notice">Một góc độ chưa hoàn tất: '+esc(w.message)+'</div>');if(!report.entries.length)notes.push('<div class="notice">Chưa trích được giá có nguồn đủ rõ. Xem nguồn tham chiếu hoặc bổ sung giá thủ công; không tạo giá thay thế.</div>');if(report.entries.some(e=>e.old))notes.push('<div class="notice">Có nguồn cũ hơn 6 tháng. Bản ghi cũ bị loại khi có nguồn mới; xem lý do trong bảng.</div>');if(report.fx)notes.push('<div class="notice">Tỷ giá dùng: '+esc(report.fx.rate)+' VNĐ/USD · '+esc(report.fx.date)+' · '+link(report.fx.url,'Nguồn tỷ giá')+'</div>');if(report.entries.some(e=>e.currency==='USD'&&e.price===null))notes.push('<div class="notice">Có giá USD chưa quy đổi vì thiếu tỷ giá có nguồn. Những giá này không được tính thống kê.</div>');$('#reportWarnings').innerHTML=notes.join('');
 $('#priceChart').innerHTML=s.reseller.length?s.reseller.slice().sort((a,b)=>a.price-b.price).slice(0,7).map(e=>'<div class="price-line"><b title="'+esc(e.seller)+'">'+esc(e.seller)+'</b><div class="price-track"><i style="width:'+Math.max(2,e.price/s.max*100)+'%"></i></div><span>'+money(e.price)+'</span></div>').join('')+'<div class="range-labels"><span>Thấp '+money(s.min)+'</span><span>Trung vị '+money(s.median)+'</span></div>':empty('Chưa đủ dữ liệu tương đương','Giá có cùng thời hạn và loại tài khoản sẽ xuất hiện tại đây.','chart');
 $('#suggestedPrice').innerHTML=s.reseller.length>=3?'<div class="suggested">'+money(s.median)+'</div><p>Mức trung vị để tham khảo. Có thể chọn giá trung bình và bảo hành tốt sau khi kiểm tra giá vốn.</p>':'<div class="suggested" style="font-size:17px">Chưa đủ dữ liệu đề xuất</div><p>Cần ít nhất 3 giá reseller cùng loại. Bạn vẫn có thể tính giá từ chi phí của mình.</p>';
 $('#trendPanel').innerHTML=tr?'<div class="trend-big">'+(tr.change>0?'↑ Tăng':tr.change<0?'↓ Giảm':'→ Ổn định')+' '+new Intl.NumberFormat('vi-VN',{maximumFractionDigits:2}).format(Math.abs(tr.change))+'%</div><p class="footnote">So với '+time(tr.previous)+' · trung vị trên '+tr.count+' bản ghi cùng nguồn và gói. Tỷ lệ hiển thị làm tròn 2 chữ số.</p><div class="trend-pairs">'+tr.pairs.slice(0,6).map(p=>'<span>'+esc(p.seller)+'<br>'+money(p.before)+' → '+money(p.after)+'</span>').join('')+'</div>':'<p class="footnote">Chưa có lần khảo sát trước với cùng nguồn, tên gói, thời hạn và loại tài khoản. Hãy khảo sát lại sau để đối chiếu.</p>';
 $('#newsList').innerHTML=report.news.length?report.news.map(n=>'<article class="news-item"><small>'+esc(n.date||'Không rõ ngày đăng')+'</small><h4>'+esc(n.title)+'</h4><p>'+esc(n.detail)+'</p>'+link(n.url,'Đọc nguồn')+'</article>').join(''):empty('Chưa có tin mới được trích nguồn','Không suy ra thay đổi giá từ một lần khảo sát.','history');
 $('#marketingList').innerHTML=report.marketing.length?report.marketing.map(m=>'<article class="news-item"><p>'+esc(m.text)+'</p>'+link(m.url,'Xem thông điệp gốc')+'</article>').join(''):empty('Chưa có thông điệp quảng cáo','Xem bảng đối thủ để kiểm tra ưu đãi và bảo hành.','target');
 $('#sourcesList').innerHTML=sources.length?sources.map((s,i)=>'<a class="source-card" target="_blank" rel="noopener noreferrer" href="'+esc(url(s.url))+'"><span class="source-initial">'+(i+1).toString().padStart(2,'0')+'</span><div><b>'+esc(s.title||new URL(s.url).hostname)+'</b><small>'+esc(new URL(s.url).hostname+s.url.replace(/^https?:\/\/[^/]+/,'').slice(0,80))+'</small></div><span>↗</span></a>').join(''):empty('Chưa có nguồn tham chiếu','Thêm giá kèm đường dẫn để bắt đầu kiểm tra.','file');renderRows();calc();icons();}
function renderRows(){if(!report)return;const query=$('#rowSearch').value.toLowerCase(),filter=$('#rowFilter').value;const rows=report.entries.filter(e=>(e.seller+' '+e.plan).toLowerCase().includes(query)&&(filter==='all'||filter==='matching'&&e.period===report.period&&e.account===report.account||filter==='excluded'&&e.exclude||filter===e.type));const labels=['ĐỐI THỦ','GIÁ NIÊM YẾT','GÓI & HÌNH THỨC','BẢO HÀNH / ƯU ĐÃI','NGUỒN & KIỂM TRA'];$('#competitorTable').innerHTML=rows.length?'<div class="table-wrap"><table><thead><tr>'+labels.map(l=>'<th>'+l+'</th>').join('')+'</tr></thead><tbody>'+rows.map(e=>'<tr class="'+(e.exclude?'excluded':'')+'"><td data-label="ĐỐI THỦ"><b>'+esc(e.seller)+'</b><small>'+(e.type==='official'?'Chính hãng':'Reseller')+'</small><span class="row-badge">'+(e.origin==='search'?'AI trích xuất':e.origin==='manual'?'Nhập thủ công':'Cần kiểm tra')+'</span></td><td data-label="GIÁ NIÊM YẾT"><b>'+esc(e.price==null?(e.amount+' '+e.currency):money(e.price))+'</b>'+(e.currency==='USD'?'<small>Giá gốc: '+esc(e.amount)+' USD</small>':'')+(e.exclude?'<small>Đã loại: '+esc(e.reason)+'</small>':'')+'</td><td data-label="GÓI & HÌNH THỨC">'+esc(e.plan)+'<small>'+(e.period==='year'?'1 năm':e.period==='month'?'1 tháng':'Chưa rõ thời hạn')+' · '+esc(e.account)+'</small>'+(e.period!==report.period||e.account!==report.account?'<small>Khác loại đang thống kê</small>':'')+'</td><td data-label="BẢO HÀNH / ƯU ĐÃI">'+esc(e.warranty||'Chưa có dữ liệu')+'<small>'+esc(e.promo||'Chưa có ưu đãi được ghi nhận')+'</small></td><td data-label="NGUỒN & KIỂM TRA">'+link(e.url)+'<small>'+esc(e.date||'Không rõ ngày đăng')+(e.old?' · Nguồn cũ':'')+'</small>'+(e.quote?'<div class="row-quote">“'+esc(e.quote)+'”</div>':'')+'<div class="row-actions"><button data-toggle="'+esc(e.id)+'">'+(e.exclude?'Đưa vào thống kê':'Loại khỏi thống kê')+'</button><button data-delete-row="'+esc(e.id)+'" class="delete-row-button" aria-label="Xóa nguồn" title="Xóa nguồn">'+icon('trash')+'</button></div></td></tr>').join('')+'</tbody></table></div>':empty('Không có bản ghi phù hợp','Thử bộ lọc khác hoặc thêm giá có nguồn.','search');$$('[data-toggle]').forEach(b=>b.onclick=async()=>{const row=report.entries.find(e=>e.id===b.dataset.toggle);if(row.exclude){row.exclude=false;row.reason=''}else{const reason=await confirmAction('Loại bản ghi khỏi thống kê?','Bản ghi vẫn được giữ trong báo cáo cùng lý do loại.',true);if(!reason)return;row.exclude=true;row.reason=reason}saveReport();renderReport()});$$('[data-delete-row]').forEach(b=>b.onclick=async()=>{if(!await confirmAction('Xóa bản ghi này?','Giá và đường dẫn sẽ được xóa khỏi báo cáo đang xem.'))return;report.entries=report.entries.filter(e=>e.id!==b.dataset.deleteRow);saveReport();renderReport()});icons()}
$('#rowSearch').oninput=renderRows;$('#rowFilter').onchange=renderRows;
function calc(){const cost=$('#costInput').value,margin=$('#marginInput').value;$('#calcResult').textContent=cost!==''&&margin!==''&&Number(cost)>=0&&Number(margin)>=0&&Number(margin)<100?'Giá bán cần đạt: '+money(Number(cost)/(1-Number(margin)/100))+'. Công thức: giá vốn / (1 − tỷ suất lợi nhuận). Chưa gồm phí và thuế.':'Nhập giá vốn và tỷ suất để tính mức giá cần bán.'}$('#costInput').oninput=calc;$('#marginInput').oninput=calc;
function addManual(){if(!report){const f=formData();if(!f.product){toast('Nhập tên sản phẩm trước khi thêm nguồn.');$('#productInput').focus();return}report=normalizeReport({id:id(),product:f.product,period:f.period,account:f.account,createdAt:new Date().toISOString(),entries:[],mode:'manual'})}$('#entryForm').reset();$('#entryForm').elements.period.value=report.period;$('#entryForm').elements.account.value=report.account;$('#entryDialog').showModal()}
$('#manualStart').onclick=addManual;$('#addEntryBtn').onclick=addManual;
$('#entryForm').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(!url(v.url))return toast('Nguồn cần đường dẫn HTTP hoặc HTTPS.');if(v.date&&new Date(v.date)>new Date())return toast('Ngày nguồn không thể nằm trong tương lai.');const cut=new Date();cut.setMonth(cut.getMonth()-6);const old=!!v.date&&new Date(v.date)<cut;if(old&&!await confirmAction('Nguồn cũ hơn 6 tháng','Chỉ dùng khi không tìm được nguồn mới. Bạn vẫn muốn thêm?'))return;const amount=Number(v.amount),fx=v.currency==='USD'?report.fx:null;report.entries.push({...v,id:id(),url:url(v.url),amount,price:v.currency==='VND'?amount:fx?amount*fx.rate:null,fx,old,origin:'manual',exclude:false,reviewed:true});report.sources.push({url:url(v.url),title:v.seller});if(v.promo)report.marketing.push({text:v.seller+': '+v.promo,url:url(v.url)});saveReport();$('#entryDialog').close();renderReport();setTab('competitors');toast('Đã lưu giá và nguồn vào báo cáo.')};
$('#rerunBtn').onclick=()=>{if(report){$('#productInput').value=report.product;$('#periodInput').value=report.period;$('#accountInput').value=report.account;beginResearch(formData())}};
$('#watchBtn').onclick=()=>{if(!report)return;const key=[report.product.toLowerCase(),report.period,report.account].join('|');if(watchlist.some(w=>w.key===key))return toast('Sản phẩm đã có trong danh sách theo dõi.');watchlist.push({id:id(),key,product:report.product,period:report.period,account:report.account});persist();toast('Đã theo dõi. Khảo sát lại từ danh sách sản phẩm.')};
function renderHistory(){const q=$('#historySearch').value.toLowerCase();const list=reports.filter(r=>r.product.toLowerCase().includes(q)).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));$('#historyList').innerHTML=list.length?list.map(r=>'<article class="history-card"><div class="report-initial">'+esc(r.product.charAt(0))+'</div><div class="history-info"><h3>'+esc(r.product)+'</h3><p>'+time(r.createdAt)+' · '+(r.period==='year'?'1 năm':'1 tháng')+' · '+esc(r.account)+' · '+r.entries.length+' giá</p></div><div class="history-price">'+money(stats(r).median)+'<small>Trung vị reseller</small></div><div class="history-actions"><button data-open="'+esc(r.id)+'">Mở báo cáo →</button><button data-rerun="'+esc(r.id)+'" aria-label="Khảo sát lại">'+icon('refresh')+'</button><button data-remove-report="'+esc(r.id)+'" aria-label="Xóa báo cáo">'+icon('trash')+'</button></div></article>').join(''):empty('Chưa có báo cáo phù hợp','Báo cáo được lưu tự động sau mỗi lần nghiên cứu. Bạn cũng có thể nhập bản sao JSON.','history');$$('[data-open]').forEach(b=>b.onclick=()=>loadReport(reports.find(r=>r.id===b.dataset.open)));$$('[data-rerun]').forEach(b=>b.onclick=()=>{const r=reports.find(r=>r.id===b.dataset.rerun);loadReport(r);beginResearch({product:r.product,period:r.period,account:r.account,depth})});$$('[data-remove-report]').forEach(b=>b.onclick=async()=>{if(!await confirmAction('Xóa báo cáo đã lưu?','Bạn có thể xuất JSON trước khi xóa để giữ bản sao.'))return;reports=reports.filter(r=>r.id!==b.dataset.removeReport);persist();renderHistory()});icons()}
$('#historySearch').oninput=renderHistory;
function renderWatchlist(){$('#watchList').innerHTML=watchlist.length?watchlist.map(w=>{const last=reports.filter(r=>r.product.toLowerCase()===w.product.toLowerCase()&&r.period===w.period&&r.account===w.account).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0];return '<article class="watch-card"><button class="icon-button" data-unwatch="'+esc(w.id)+'" aria-label="Bỏ theo dõi">'+icon('x')+'</button><div class="report-initial">'+esc(w.product.charAt(0))+'</div><h3>'+esc(w.product)+'</h3><p>'+(w.period==='year'?'1 năm':'1 tháng')+' · '+esc(w.account)+'</p><div class="watch-stat">'+(last?money(stats(last).median):'Chưa khảo sát')+'<small>'+(last?'Lần cuối '+time(last.createdAt):'Chưa có dữ liệu')+'</small></div><button class="primary" data-scan-watch="'+esc(w.id)+'">Khảo sát ngay '+icon('arrow')+'</button></article>'}).join(''):empty('Sản phẩm quan tâm, luôn trong tầm mắt','Nhấn Theo dõi trong một báo cáo để lưu sản phẩm và khảo sát lại nhanh.','bookmark');$$('[data-unwatch]').forEach(b=>b.onclick=async()=>{if(!await confirmAction('Bỏ theo dõi sản phẩm?','Các báo cáo đã lưu vẫn được giữ.'))return;watchlist=watchlist.filter(w=>w.id!==b.dataset.unwatch);persist();renderWatchlist()});$$('[data-scan-watch]').forEach(b=>b.onclick=()=>{const w=watchlist.find(w=>w.id===b.dataset.scanWatch);$('#productInput').value=w.product;$('#periodInput').value=w.period;$('#accountInput').value=w.account;beginResearch(formData())});icons()}
function download(data,name,type){const b=new Blob([data],{type}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('#exportBtn').onclick=()=>$('#exportDialog').showModal();$('#downloadMd').onclick=()=>{download(markdown(report,reports),'giasat-bao-cao.md','text/markdown;charset=utf-8');toast('Đã xuất báo cáo Markdown.')};$('#downloadJson').onclick=()=>download(JSON.stringify(report,null,2),'giasat-bao-cao.json','application/json');$('#copyReport').onclick=async()=>{try{await navigator.clipboard.writeText(markdown(report,reports));toast('Đã sao chép báo cáo.')}catch{toast('Trình duyệt chưa cho sao chép. Hãy tải bản Markdown.')}};
$('#backupBtn').onclick=()=>download(JSON.stringify({version:2,reports,watchlist},null,2),'giasat-sao-luu.json','application/json');$('#importBtn').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024){toast('Tệp tối đa 5 MB.');e.target.value='';return}try{const data=JSON.parse(await f.text()),items=Array.isArray(data)?data:Array.isArray(data.reports)?data.reports:[data],incoming=items.map(normalizeReport);reports=[...new Map([...reports,...incoming].map(r=>[r.id,r])).values()].slice(0,80);if(Array.isArray(data.watchlist))for(const w of data.watchlist){if(typeof w.product==='string'&&['month','year'].includes(w.period)&&['Chính chủ','Cấp riêng','Dùng chung','Chưa rõ'].includes(w.account)){const key=[w.product.toLowerCase(),w.period,w.account].join('|');if(!watchlist.some(v=>v.key===key))watchlist.push({...w,id:id(),key})}}persist();renderHistory();toast('Đã nhập '+incoming.length+' báo cáo.')}catch(err){toast(err.message||'Không đọc được tệp JSON.')}finally{e.target.value=''}};
$('#imageForm').onsubmit=async e=>{e.preventDefault();if(!connected||!ready){await openConnect();return}$('#imageBtn').disabled=true;$('#imageResults').innerHTML='<div class="loading-placeholder"></div><div class="loading-placeholder"></div><div class="loading-placeholder"></div>';try{const result=await api('/api/images',{method:'POST',body:{product:$('#imageProduct').value.trim()},timeout:160000});$('#imageResults').innerHTML=result.images.length?result.images.map(i=>'<article class="image-card"><div class="image-preview"><img loading="lazy" referrerpolicy="no-referrer" src="'+esc(url(i.imageUrl))+'" alt="'+esc(i.title)+'"></div><div class="image-info"><h3>'+esc(i.title)+'</h3>'+link(i.sourceUrl,'Trang nguồn')+link(i.imageUrl,'Mở ảnh')+'</div></article>').join(''):empty('Chưa tìm được URL ảnh đủ rõ nguồn','Thử tên sản phẩm cụ thể hơn. Không tạo URL thay thế.','image');$$('.image-preview img').forEach(img=>img.onerror=()=>{img.parentElement.innerHTML='<span class="muted small">Ảnh không cho phép xem nhúng.<br>Hãy mở ảnh hoặc trang nguồn.</span>'});icons()}catch(err){$('#imageResults').innerHTML=empty('Chưa hoàn tất tìm ảnh',err.message,'image');icons()}finally{$('#imageBtn').disabled=false}};
icons();counts();statusUI();checkConnection(true).then(ok=>{if(ok){try{const pending=sessionStorage.getItem('giasat-job');if(pending){job=pending;pollJob()}}catch{}}});



